   134→// runEnableWithStrategy enables Entire with a specified strategy (non-interactive).
   135→// The selectedStrategy can be either a display name (manual-commit, auto-commit)
   136→// or an internal name (manual-commit, auto-commit).
   137→func runEnableWithStrategy(w io.Writer, selectedStrategy string, localDev, _, useLocalSettings, useProjectSettings, forceHooks, setupShell, skipPushSessions, noTelemetry bool, disableMultisessionWarning bool) error {
   138→	// Map the strategy to internal name if it's a display name
   139→	internalStrategy := selectedStrategy
   140→	if mapped, ok := strategyDisplayToInternal[selectedStrategy]; ok {
   141→		internalStrategy = mapped
   142→	}
   143→
   144→	// Validate the strategy exists
   145→	strat, err := strategy.Get(internalStrategy)
   146→	if err != nil {
   147→		return fmt.Errorf("unknown strategy: %s (use manual-commit or auto-commit)", selectedStrategy)
   148→	}
   149→
   150→	// Setup Claude Code hooks
   151→	hooksInstalled, err := setupClaudeCodeHook(localDev, forceHooks)
   152→	if err != nil {
   153→		return fmt.Errorf("failed to setup Claude Code hooks: %w", err)
   154→	}
   155→	if hooksInstalled > 0 {
   156→		fmt.Fprintln(w, "✓ Claude Code hooks installed")
   157→	} else {
   158→		fmt.Fprintln(w, "✓ Claude Code hooks verified")
   159→	}
   160→
   161→	// Setup .entire directory
   162→	dirCreated, err := setupEntireDirectory()
   163→	if err != nil {
   164→		return fmt.Errorf("failed to setup .entire directory: %w", err)
   165→	}
   166→	if dirCreated {
   167→		fmt.Fprintln(w, "✓ .entire directory created")
   168→	}
   169→
   170→	// Load existing settings to preserve other options (like strategy_options.push)
   171→	settings, err := LoadEntireSettings()
   172→	if err != nil {
   173→		// If we can't load, start with defaults
   174→		settings = &EntireSettings{}
   175→	}
   176→	// Update the specific fields
   177→	settings.Strategy = internalStrategy
   178→	settings.LocalDev = localDev
   179→	settings.Enabled = true
   180→
   181→	// Set push_sessions option if --skip-push-sessions flag was provided
   182→	if skipPushSessions {
   183→		if settings.StrategyOptions == nil {
   184→			settings.StrategyOptions = make(map[string]interface{})
   185→		}
   186→		settings.StrategyOptions["push_sessions"] = false
   187→	}
   188→
   189→	// Set disable_multisession_warning option if --disable-multisession-warning flag was provided
   190→	if disableMultisessionWarning {
   191→		if settings.StrategyOptions == nil {
   192→			settings.StrategyOptions = make(map[string]interface{})
   193→		}
   194→		settings.StrategyOptions["disable_multisession_warning"] = true
   195→	}
   196→
   197→	// Handle telemetry for non-interactive mode
   198→	if noTelemetry || os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
   199→		// --no-telemetry flag always overrides existing setting
   200→		f := false
   201→		settings.Telemetry = &f
   202→	} else if settings.Telemetry == nil {
   203→		// Default to enabled in non-interactive mode (only if not already set)
   204→		t := true
   205→		settings.Telemetry = &t
   206→	}
   207→
   208→	// Determine which settings file to write to
   209→	entireDirAbs, err := paths.AbsPath(paths.EntireDir)
   210→	if err != nil {
   211→		entireDirAbs = paths.EntireDir // Fallback to relative
   212→	}
   213→	shouldUseLocal, showNotification := determineSettingsTarget(entireDirAbs, useLocalSettings, useProjectSettings)
   214→
   215→	if showNotification {
   216→		fmt.Fprintln(w, "Info: Project settings exist. Saving to settings.local.json instead.")
   217→		fmt.Fprintln(w, "  Use --project to update the project settings file.")
   218→	}
   219→
   220→	if shouldUseLocal {
   221→		if err := SaveEntireSettingsLocal(settings); err != nil {
   222→			return fmt.Errorf("failed to save local settings: %w", err)
   223→		}
   224→		fmt.Fprintln(w, "✓ Local settings saved (.entire/settings.local.json)")
   225→	} else {
   226→		if err := SaveEntireSettings(settings); err != nil {
   227→			return fmt.Errorf("failed to save settings: %w", err)
   228→		}
   229→		fmt.Fprintln(w, "✓ Project settings saved (.entire/settings.json)")
   230→	}
   231→
   232→	// Install git hooks (always reinstall to ensure they're up-to-date)
   233→	gitHooksInstalled, err := strategy.InstallGitHook(true)
   234→	if err != nil {
   235→		return fmt.Errorf("failed to install git hooks: %w", err)
   236→	}
   237→	if gitHooksInstalled > 0 {
   238→		fmt.Fprintln(w, "✓ Git hooks installed")
   239→	} else {
   240→		fmt.Fprintln(w, "✓ Git hooks verified")
   241→	}
   242→
   243→	// Let the strategy handle its own setup requirements
   244→	if err := strat.EnsureSetup(); err != nil {
   245→		return fmt.Errorf("failed to setup strategy: %w", err)
   246→	}
   247→
   248→	// Setup shell completion if --setup-shell flag was provided
   249→	if setupShell {
   250→		if err := setupShellCompletionNonInteractive(w); err != nil {
   251→			// Non-fatal - just log and continue
   252→			fmt.Fprintf(w, "Note: Shell completion setup skipped: %v\n", err)
   253→		}
   254→	}
   255→
   256→	// Show success message with display name
   257→	displayName := selectedStrategy
   258→	if dn, ok := strategyInternalToDisplay[internalStrategy]; ok {
   259→		displayName = dn
   260→	}
   261→	fmt.Fprintf(w, "\n✓ %s strategy enabled\n", displayName)
   262→
   263→	return nil
   264→}
