   407→// runEnable is a simple enable that just sets the enabled flag (for programmatic use).
   408→func runEnable(w io.Writer) error {
   409→	settings, err := LoadEntireSettings()
   410→	if err != nil {
   411→		return fmt.Errorf("failed to load settings: %w", err)
   412→	}
   413→
   414→	settings.Enabled = true
   415→	if err := SaveEntireSettings(settings); err != nil {
   416→		return fmt.Errorf("failed to save settings: %w", err)
   417→	}
   418→
   419→	fmt.Fprintln(w, "Entire is now enabled.")
   420→	return nil
   421→}
