   573→// setupAgentHooksNonInteractive sets up hooks for a specific agent non-interactively.
   574→// If strategyName is provided, it sets the strategy; otherwise uses default.
   575→func setupAgentHooksNonInteractive(agentName, strategyName string, localDev, forceHooks, skipPushSessions, noTelemetry, disableMultisessionWarning bool) error {
   576→	ag, err := agent.Get(agentName)
   577→	if err != nil {
   578→		return fmt.Errorf("unknown agent: %s", agentName)
   579→	}
   580→
   581→	// Check if agent supports hooks
   582→	hookAgent, ok := ag.(agent.HookSupport)
   583→	if !ok {
   584→		return fmt.Errorf("agent %s does not support hooks", agentName)
   585→	}
   586→
   587→	// Install hooks
   588→	count, err := hookAgent.InstallHooks(localDev, forceHooks)
   589→	if err != nil {
   590→		return fmt.Errorf("failed to install hooks for %s: %w", agentName, err)
   591→	}
   592→
   593→	if count == 0 {
   594→		msg := fmt.Sprintf("Hooks for %s already installed", ag.Description())
   595→		if agentName == agent.AgentNameGemini {
   596→			msg += " - This is a work in progress"
   597→		}
   598→		fmt.Println(msg)
   599→	} else {
   600→		msg := fmt.Sprintf("Installed %d hooks for %s", count, ag.Description())
   601→		if agentName == agent.AgentNameGemini {
   602→			msg += " - This is a work in progress"
   603→		}
   604→		fmt.Println(msg)
   605→	}
   606→
   607→	// Update settings to store the agent choice and strategy
   608→	settings, _ := LoadEntireSettings() //nolint:errcheck // settings defaults are fine
   609→	settings.Agent = agentName
   610→	settings.Enabled = true
   611→	if localDev {
   612→		settings.LocalDev = localDev
   613→	}
   614→
   615→	// Set push_sessions option if --skip-push-sessions flag was provided
   616→	if skipPushSessions {
   617→		if settings.StrategyOptions == nil {
   618→			settings.StrategyOptions = make(map[string]interface{})
   619→		}
   620→		settings.StrategyOptions["push_sessions"] = false
   621→	}
   622→
   623→	// Set disable_multisession_warning option if --disable-multisession-warning flag was provided
   624→	if disableMultisessionWarning {
   625→		if settings.StrategyOptions == nil {
   626→			settings.StrategyOptions = make(map[string]interface{})
   627→		}
   628→		settings.StrategyOptions["disable_multisession_warning"] = true
   629→	}
   630→
   631→	// Set strategy if provided
   632→	if strategyName != "" {
   633→		// Map display name to internal name if needed
   634→		internalStrategy := strategyName
   635→		if mapped, ok := strategyDisplayToInternal[strategyName]; ok {
   636→			internalStrategy = mapped
   637→		}
   638→		// Validate the strategy exists
   639→		if _, err := strategy.Get(internalStrategy); err != nil {
   640→			return fmt.Errorf("unknown strategy: %s (use manual-commit or auto-commit)", strategyName)
   641→		}
   642→		settings.Strategy = internalStrategy
   643→	}
   644→
   645→	// Handle telemetry for non-interactive mode
   646→	if noTelemetry || os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
   647→		// --no-telemetry flag always overrides existing setting
   648→		f := false
   649→		settings.Telemetry = &f
   650→	} else if settings.Telemetry == nil {
   651→		// Default to enabled in non-interactive mode (only if not already set)
   652→		t := true
   653→		settings.Telemetry = &t
   654→	}
   655→
   656→	if err := SaveEntireSettings(settings); err != nil {
   657→		return fmt.Errorf("failed to save settings: %w", err)
   658→	}
   659→
   660→	// Install git hooks (always reinstall to ensure they're up-to-date)
   661→	if _, err := strategy.InstallGitHook(true); err != nil {
   662→		return fmt.Errorf("failed to install git hooks: %w", err)
   663→	}
   664→
   665→	// Let the strategy handle its own setup requirements (creates entire/sessions branch, etc.)
   666→	strat, err := strategy.Get(settings.Strategy)
   667→	if err != nil {
   668→		return fmt.Errorf("failed to get strategy: %w", err)
   669→	}
   670→	if err := strat.EnsureSetup(); err != nil {
   671→		return fmt.Errorf("failed to setup strategy: %w", err)
   672→	}
