   688→// Returns (useLocal, showNotification).
   689→func determineSettingsTarget(entireDir string, useLocal, useProject bool) (bool, bool) {
   690→	// Explicit --local flag always uses local settings
   691→	if useLocal {
   692→		return true, false
   693→	}
   694→
   695→	// Explicit --project flag always uses project settings
   696→	if useProject {
   697→		return false, false
   698→	}
   699→
   700→	// No flags specified - check if settings file exists
   701→	settingsPath := filepath.Join(entireDir, paths.SettingsFileName)
   702→	if _, err := os.Stat(settingsPath); err == nil {
   703→		// Settings file exists - auto-redirect to local with notification
   704→		return true, true
   705→	}
   706→
   707→	// Settings file doesn't exist - create it
   708→	return false, false
   709→}
