   813→// shellCompletionComment is the comment preceding the completion line
   814→const shellCompletionComment = "# Entire CLI shell completion"
   815→
   816→// promptShellCompletion offers to add shell completion to the user's rc file.
   817→// Only prompts if completion is not already configured.
   818→func promptShellCompletion(w io.Writer) error {
   819→	// Get user's home directory
   820→	home, err := os.UserHomeDir()
   821→	if err != nil {
   822→		//nolint:nilerr // Skip silently if we can't determine home - not a fatal error
   823→		return nil
   824→	}
   825→
   826→	// Determine shell and rc file
   827→	shell := os.Getenv("SHELL")
   828→	var rcFile string
   829→	var completionLine string
   830→
   831→	switch {
   832→	case strings.Contains(shell, "zsh"):
   833→		rcFile = filepath.Join(home, ".zshrc")
   834→		completionLine = "source <(entire completion zsh)"
   835→	case strings.Contains(shell, "bash"):
   836→		rcFile = filepath.Join(home, ".bashrc")
   837→		completionLine = "source <(entire completion bash)"
   838→	default:
   839→		return nil // Unsupported shell, skip silently
   840→	}
   841→
   842→	// Check if completion is already configured
   843→	if isCompletionConfigured(rcFile) {
   844→		return nil // Already configured, skip silently
   845→	}
   846→
   847→	// Prompt user with select-style picker (matching other prompts)
   848→	var selected string
   849→	form := NewAccessibleForm(
   850→		huh.NewGroup(
   851→			huh.NewSelect[string]().
   852→				Title("Enable shell completion?").
   853→				Options(
   854→					huh.NewOption("Yes", "yes"),
   855→					huh.NewOption("No", "no"),
   856→				).
   857→				Value(&selected),
   858→		),
   859→	)
   860→
   861→	if err := form.Run(); err != nil {
   862→		//nolint:nilerr // User cancelled - not a fatal error, just skip
   863→		return nil
   864→	}
   865→
   866→	if selected != "yes" {
   867→		return nil
   868→	}
   869→
   870→	// Append completion to rc file
   871→	if err := appendShellCompletion(rcFile, completionLine); err != nil {
   872→		return fmt.Errorf("failed to update %s: %w", rcFile, err)
   873→	}
   874→
   875→	fmt.Fprintf(w, "✓ Shell completion added to %s\n", rcFile)
   876→	fmt.Fprintln(w, "  Run `source "+rcFile+"` or restart your shell to activate")
   877→
   878→	return nil
   879→}
