   881→// isCompletionConfigured checks if shell completion is already in the rc file.
   882→func isCompletionConfigured(rcFile string) bool {
   883→	//nolint:gosec // G304: rcFile is constructed from home dir + known filename, not user input
   884→	content, err := os.ReadFile(rcFile)
   885→	if err != nil {
   886→		return false // File doesn't exist or can't read, treat as not configured
   887→	}
   888→	return strings.Contains(string(content), "entire completion")
   889→}
   890→
   891→// appendShellCompletion adds the completion line to the rc file.
   892→func appendShellCompletion(rcFile, completionLine string) error {
   893→	//nolint:gosec // G302: Shell rc files need 0644 for user readability
   894→	f, err := os.OpenFile(rcFile, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
   895→	if err != nil {
   896→		return fmt.Errorf("opening file: %w", err)
   897→	}
   898→	defer f.Close()
   899→
   900→	// Add newline, comment, and completion line
   901→	_, err = f.WriteString("\n" + shellCompletionComment + "\n" + completionLine + "\n")
   902→	if err != nil {
   903→		return fmt.Errorf("writing completion: %w", err)
   904→	}
   905→	return nil
   906→}
