    58→// If force is true, removes existing Entire hooks before installing.
    59→// Returns the number of hooks installed.
    60→func (c *ClaudeCodeAgent) InstallHooks(localDev bool, force bool) (int, error) {
    61→	// Use repo root instead of CWD to find .claude directory
    62→	// This ensures hooks are installed correctly when run from a subdirectory
    63→	repoRoot, err := paths.RepoRoot()
