    88→				return 0, fmt.Errorf("failed to parse hooks in settings.json: %w", err)
    89→			}
    90→		}
    91→		if permRaw, ok := rawSettings["permissions"]; ok {
    92→			if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
    93→				return 0, fmt.Errorf("failed to parse permissions in settings.json: %w", err)
    94→			}
    95→		}
    96→	} else {
    97→		rawSettings = make(map[string]json.RawMessage)
    98→	}
    99→
   100→	if rawPermissions == nil {
   101→		rawPermissions = make(map[string]json.RawMessage)
   102→	}
